import{c as e,Q as r,j as a,m as o}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Learning Checklist — Routine 補閉環 · read-path 斷點","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-07-20-routine-closure-learning.md","filePath":"research/reports/2026-07-20-routine-closure-learning.md","lastUpdated":1785909234000}'),i={name:"research/reports/2026-07-20-routine-closure-learning.md"};function d(n,t,s,l,h,c){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="learning-checklist-—-routine-補閉環-·-read-path-斷點" tabindex="-1">Learning Checklist — Routine 補閉環 · read-path 斷點 <a class="header-anchor" href="#learning-checklist-—-routine-補閉環-·-read-path-斷點" aria-label="Permalink to &quot;Learning Checklist — Routine 補閉環 · read-path 斷點&quot;">​</a></h1><blockquote><p>/teach session 2026-07-20 · 基底：<code>2026-07-20-loop-engineering-harness-insight.md</code> 狀態：⬜ 未教 · 🟡 教學中 · ✅ 已展示理解</p></blockquote><table tabindex="0"><thead><tr><th>#</th><th>概念</th><th>①問題</th><th>②解法</th><th>③脈絡</th><th>狀態</th></tr></thead><tbody><tr><td>C1</td><td>為何閉環會「忘記/無法執行」——問題的真形狀（不是排程缺席，是 read-path 斷 + 人是唯一觸發器）</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>C2</td><td>Routine 能補什麼、不能補什麼（觸發器 vs 電路；cron 打進斷的 read-path = 空轉，例證：R1/B1 routine 已存在仍空轉）</td><td>✅</td><td>✅（首測誤選 dreaming，補「觸發時機形狀」判準後重測過）</td><td>✅</td><td>✅</td></tr><tr><td>C3</td><td>正確順序：① trace capture（session-stop.sh skills_used）→ ② dreaming 接線 → ③ eval 閘；routine 只在電路通了之後才有東西可推</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>C4</td><td>自動化的安全邊界：外部 oracle 前置、不可逆處人閘、routine 自身要寫 heartbeat（可被監控）</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr></tbody></table><h2 id="學習日誌" tabindex="-1">學習日誌 <a class="header-anchor" href="#學習日誌" aria-label="Permalink to &quot;學習日誌&quot;">​</a></h2><ul><li>開場 restate：「該讀的資料有缺、做法不確定」→ 定位缺口：對 write/read path 的區分未成形。</li><li>C1 首測誤判「routine 會被卡住報錯」→ 補「空轉不報錯比 crash 更危險（B1 16 天假信心）」→ 重測過（正確指認 B1）。</li><li>C2 首測誤選 dreaming 為錯誤用途 → 補「觸發時機形狀」判準（時間驅動→routine／事件驅動→hook／欄位沒寫→改 code）→ 重測過（push 前 review=hook、每日報告=routine）。</li><li>C3 一次過：跳過①的後果（讀 [] 空轉）+ 正確第一步（合成 transcript 先驗 oracle）。</li><li>C4 一次過：自評=中間態、外部 oracle 前置、consolidation 人閘。</li><li>終局復述（學習者原話）：「把流程走過一遍，沿路要補完一些東西，才能把流程串在一起；且審閱過才能併入主線做為下次的累積經驗」——命中電路先於觸發器 + oracle/人閘兩根主樑。</li></ul><h2 id="標準版答案-存底" tabindex="-1">標準版答案（存底） <a class="header-anchor" href="#標準版答案-存底" aria-label="Permalink to &quot;標準版答案（存底）&quot;">​</a></h2><p><strong>「閉環忘記/無法執行，可用 routine 補齊嗎？」</strong></p><ul><li><strong>能補</strong>：觸發自主性（人是單點故障的部分）——每週 dreaming 蒸餾、定期 harness sweep 稽核、heartbeat 新鮮度檢查（皆時間驅動）。</li><li><strong>不能補</strong>：point-of-need retrieval（LESSONS→動作前提醒，事件驅動 → hook）；trace capture 斷線（session-stop.sh 沒寫 skills_used → 改 code）；不可逆核可（永遠人閘）。</li><li><strong>順序</strong>：① 修 trace capture（oracle-first：合成 transcript 先驗）→ ② dreaming 接 task-log → ③ eval 閘 → ④ routine 排程。倒序 = B1 式空轉（不報錯的假信心）。</li><li><strong>邊界</strong>：自動迴圈產出候選=中間態，過外部/異模型 oracle 才算數；merge/不可逆處人閘；routine 自身寫 heartbeat 可被監控。修閉環的動作本身也要過閉環的閘（A1 例）。</li></ul>',8)])])}const g=e(i,[["render",d]]);export{p as __pageData,g as default};
